UPDATE refresh_sessions
SET revoked_at      = #{revokedAt},
    revoked_reason  = #{reason}
WHERE id = #{id}
  AND revoked_at IS NULL

UPDATE refresh_sessions
SET revoked_at      = #{revokedAt},
    revoked_reason  = #{reason}
WHERE user_id = #{userId}
  AND family_id <> #{familyId}::uuid
  AND revoked_at IS NULL

